// FLOYD-WARSHALL ALL-PAIRS SHORTEST PATH
// O(V^3) time, O(V^2) space
function floydWarshall(graph) {
    const V = graph.length;
    // dist[i][j] = shortest path from i to j
    const dist = graph.map(row => [...row]); // copy

    // Ensure dist[i][i] = 0 and undefined edges = Infinity
    for (let i = 0; i < V; i++) {
        for (let j = 0; j < V; j++) {
            if (i === j) dist[i][j] = 0;
            else if (dist[i][j] === undefined || dist[i][j] === null) {
                dist[i][j] = Infinity;
            }
        }
    }

    // Main DP: try each vertex as intermediate
    for (let k = 0; k < V; k++) {
        for (let i = 0; i < V; i++) {
            for (let j = 0; j < V; j++) {
                if (dist[i][k] + dist[k][j] < dist[i][j]) {
                    dist[i][j] = dist[i][k] + dist[k][j];
                }
            }
        }
    }

    // NEGATIVE CYCLE DETECTION
    for (let i = 0; i < V; i++) {
        if (dist[i][i] < 0) return null; // negative cycle detected
    }
    return dist;
}

