// FIND THE CITY WITH FEWEST NEIGHBOURS (#1334, NeetCode 150)
// Using Floyd-Warshall to compute all-pairs distances
function findTheCity(n, edges, distanceThreshold) {
    const dist = Array.from({length:n}, (_, i) =>
        Array.from({length:n}, (_, j) => (i===j ? 0 : Infinity)));
    for (const [u,v,w] of edges) { dist[u][v] = w; dist[v][u] = w; }

    for (let k=0;k<n;k++)
        for (let i=0;i<n;i++)
            for (let j=0;j<n;j++)
                dist[i][j] = Math.min(dist[i][j], dist[i][k]+dist[k][j]);

    let result = 0, minCount = Infinity;
    for (let i=0;i<n;i++) {
        const count = dist[i].filter((d,j)=>j!==i && d<=distanceThreshold).length;
        if (count <= minCount) { minCount = count; result = i; } // prefer larger index
    }
    return result;
}
