// TARJAN'S SCC ALGORITHM — O(V+E)
function tarjanSCC(n, edges) {
    const adj = Array.from({length:n}, ()=>[]);
    for (const [u,v] of edges) adj[u].push(v);

    const disc = new Array(n).fill(-1); // discovery time
    const low  = new Array(n).fill(-1); // low-link value
    const onStack = new Array(n).fill(false);
    const stack  = [];
    const sccs   = [];
    let timer = 0;

    function dfs(v) {
        disc[v] = low[v] = timer++;
        stack.push(v);
        onStack[v] = true;

        for (const u of adj[v]) {
            if (disc[u] === -1) {
                // Tree edge: recurse
                dfs(u);
                low[v] = Math.min(low[v], low[u]); // propagate low from child
            } else if (onStack[u]) {
                // Back edge to vertex on stack: update low
                low[v] = Math.min(low[v], disc[u]);
            }
            // Cross edge (disc[u]!=-1 && !onStack[u]): ignore
        }

        // If v is SCC root: pop all vertices in this SCC
        if (low[v] === disc[v]) {
            const scc = [];
            let w;
            do {
                w = stack.pop();
                onStack[w] = false;
                scc.push(w);
            } while (w !== v);
            sccs.push(scc);
        }
    }

    for (let v = 0; v < n; v++) {
        if (disc[v] === -1) dfs(v); // handle disconnected components
    }
    return sccs;
}

