// BRIDGES AND ARTICULATION POINTS — O(V+E)
function findBridgesAndArticulations(n, edges) {
    const adj = Array.from({length:n}, ()=>[]);
    for (const [u,v] of edges) { adj[u].push(v); adj[v].push(u); }

    const disc = new Array(n).fill(-1);
    const low  = new Array(n).fill(-1);
    const bridges = [];
    const artPoints = new Set();
    let timer = 0;

    function dfs(v, parent) {
        disc[v] = low[v] = timer++;
        let childCount = 0;

        for (const u of adj[v]) {
            if (u === parent) continue; // skip the edge we came from
            if (disc[u] === -1) {
                // Tree edge
                childCount++;
                dfs(u, v);
                low[v] = Math.min(low[v], low[u]); // propagate low from child

                // BRIDGE: no back edge from u's subtree bypasses edge (v,u)
                if (low[u] > disc[v]) bridges.push([v, u]);

                // ARTICULATION POINT: u's subtree cannot bypass v
                if (disc[v] !== 0 && low[u] >= disc[v]) artPoints.add(v);
                // Root case: handled below
            } else {
                // Back edge: update low
                low[v] = Math.min(low[v], disc[u]);
            }
        }
        // Root is articulation point if it has 2+ DFS tree children
        if (disc[v] === 0 && childCount >= 2) artPoints.add(v);
    }

    for (let v = 0; v < n; v++) if (disc[v] === -1) dfs(v, -1);
    return { bridges, artPoints: [...artPoints] };
}

