// MAXIMUM BIPARTITE MATCHING — augmenting path, O(VE)
function maxBipartiteMatching(leftCount, rightCount, edges) {
    // Build adjacency from left to right
    const adj = Array.from({length:leftCount}, ()=>[]);
    for (const [l,r] of edges) adj[l].push(r);

    const matchL = new Array(leftCount).fill(-1);  // matchL[l] = matched right vertex
    const matchR = new Array(rightCount).fill(-1); // matchR[r] = matched left vertex

    // Try to find augmenting path from left vertex u
    function dfs(u, visited) {
        for (const v of adj[u]) {
            if (visited[v]) continue; // already tried this right vertex
            visited[v] = true;
            // v is free OR v's current match can find another partner
            if (matchR[v] === -1 || dfs(matchR[v], visited)) {
                matchL[u] = v;
                matchR[v] = u;
                return true; // augmenting path found
            }
        }
        return false; // no augmenting path from u
    }

    let matching = 0;
    for (let u = 0; u < leftCount; u++) {
        const visited = new Array(rightCount).fill(false);
        if (dfs(u, visited)) matching++;
    }
    return { matching, matchL, matchR };
}

