// EDMONDS-KARP MAX FLOW (BFS augmenting paths) — O(V * E^2)
function maxFlow(n, edges, source, sink) {
    // Build residual graph
    const cap = Array.from({length:n}, ()=>new Array(n).fill(0));
    for (const [u,v,c] of edges) cap[u][v] += c;

    let totalFlow = 0;

    while (true) {
        // BFS to find shortest augmenting path
        const parent = new Array(n).fill(-1);
        parent[source] = source;
        const queue = [source];

        while (queue.length && parent[sink] === -1) {
            const v = queue.shift();
            for (let u = 0; u < n; u++) {
                if (parent[u] === -1 && cap[v][u] > 0) {
                    parent[u] = v;
                    queue.push(u);
                }
            }
        }

        if (parent[sink] === -1) break; // no augmenting path

        // Find bottleneck capacity
        let flow = Infinity;
        for (let v = sink; v !== source; v = parent[v]) {
            flow = Math.min(flow, cap[parent[v]][v]);
        }

        // Update residual capacities
        for (let v = sink; v !== source; v = parent[v]) {
            cap[parent[v]][v] -= flow; // reduce forward capacity
            cap[v][parent[v]] += flow; // increase backward capacity
        }

        totalFlow += flow;
    }
    return totalFlow;
}

